/* Cairn – werkzeuge-b (Wardenhandbuch S. 106–147) */
CN.add("werkzeuge", {"id": "monster-erschaffen", "t": "Monster erschaffen", "p": 106, "buch": "cn_w", "b": [{"t": "h", "x": "Überblick"}, "Um ein einzigartiges Monster zu erschaffen, gehe wie folgt vor:", {"t": "ul", "x": ["Würfle auf der Tabelle Monster-Erscheinung.", "Würfle auf der Tabelle Monster-Eigenschaften.", "Würfle auf der Tabelle Monster-Angriffe.", "Würfle auf der Tabelle Monster-Fähigkeiten.", "Beschreibe Aussehen, Fähigkeiten und Angriffe der Kreatur in einfachen Worten.", "Erstelle die Werte der Kreatur nach den untenstehenden Grundsätzen, Definitionen und dem Format des Wertekastens."]}, {"t": "h", "x": "Grundsätze"}, {"t": "ul", "x": ["Nutze den kritischen Schaden, um die Bedrohlichkeit oder Fremdartigkeit jedes aggressiven NSC zu betonen.", "Nutze Besonderheiten und Stil, damit sich Kreaturen abheben. Die Spielenden erinnern sich leichter an einen schweinsgesichtigen Humanoiden, der seine verlorenen Schafe sucht, als an einen beliebigen Goblin-Bogenschützen.", "Passe die Werte einer Kreatur immer daran an, was Spaß macht und interessant ist."]}, {"t": "h", "x": "Definitionen"}, {"t": "dl", "x": [["Trefferschutz", "Die Fähigkeit einer Kreatur, Gefahr zu vermeiden, sei es durch Zähigkeit, Schnelligkeit oder Geschick. Gib durchschnittlichen Kreaturen 3 TS, hartgesottenen 6 TS und ernsthaften Bedrohungen 10 TS oder mehr."], ["Rüstung", "Bei manchen Kreaturen steht dieser Wert für ihre natürliche Zähigkeit, bei anderen für getragene oder mitgeführte Ausrüstung. Kann eine Kreatur einen Angriff aushalten, ohne sich zu bewegen, erhöhe diesen Wert."], ["Attribute", "3 ist mangelhaft, 6 ist schwach, 10 ist durchschnittlich, 14 ist bemerkenswert und 18 ist legendär."], ["Stärke (STÄ)", "Steht für allgemeine Gesundheit, körperliche Kraft und Widerstandskraft gegen Gifte. Sie beschreibt die Fähigkeit einer Kreatur, einen direkten Treffer zu überleben, nicht, Gefahr zu vermeiden!"], ["Geschicklichkeit (GES)", "Beginne mit 10 als Grundwert und erhöhe die Zahl nach Bedarf, wenn die Kreatur besonders schnell, flink oder fingerfertig ist. Ist sie langsam, sperrig oder tollpatschig, senke die Zahl."], ["Willenskraft (WIL)", "Bestimmt, wie gut eine Kreatur dem Einfluss anderer widerstehen kann und wie viel Macht sie über andere hat. Sie misst auch ihre Abwehr in magischen oder spirituellen Angelegenheiten."], ["Angriffe", "Meist ein Gegenstand (z. B. Schwert oder Bogen) oder eine natürliche Waffe (z. B. Klauen oder Zähne)."], ["Fähigkeiten", "Eine einzigartige Handlung oder Kraft, die die Kreatur sowohl im Kampf als auch außerhalb nutzen kann."]]}, {"t": "ul", "x": ["Lässt sich eine Fähigkeit mit herkömmlichen Mitteln sinnvoll vermeiden oder abwehren, ist sie ein Angriff und wirkt auf den TS.", "Lässt sich eine Fähigkeit mit herkömmlichen Mitteln nicht sinnvoll vermeiden oder abwehren, ist sie eine Fähigkeit.", "Betrifft eine Fähigkeit nur einen einzelnen SC, sollte sie in der Regel eine sofortige Wirkung ohne Rettungswurf in dieser Runde haben (siehe Basilisk, S. 83).", "Kann eine Fähigkeit eine Gruppe von SC betreffen, sollte sie in der Regel einen sofortigen Rettungswurf erfordern (siehe Grüner Drache, S. 88)."]}, {"t": "h", "x": "Format des Monster-Wertekastens"}, {"t": "box", "h": "Wertekasten", "b": ["X TS, X Rüstung, X STÄ, X GES, X WIL, Angriff (WX, besondere Gegenstände, Eigenschaften)", {"t": "ul", "x": ["Eine ansprechende Beschreibung von Aussehen, Auftreten oder Lebensweise.", "Eine Eigenheit, Taktik oder Besonderheit, die diese Kreatur auszeichnet.", "Besondere Wirkung oder Folge des kritischen Schadens."]}]}]});
CN.add("werkzeuge", {"id": "monster-tabellen", "t": "Monster-Tabellen", "p": 108, "buch": "cn_w", "b": [{"t": "h", "x": "Erscheinung"}, "Würfle für jede Spalte mit 1W20 und kombiniere die Ergebnisse.", {"t": "tbl", "head": ["W20", "Körperbau", "Merkmal"], "rows": [["1", "Albino", "Fühler"], ["2", "Schwarz", "Schnabel"], ["3", "Kristallin", "Panzer"], ["4", "Ausgemergelt", "Klauen"], ["5", "Augenlos", "Reißzähne"], ["6", "Gefiedert", "Federn"], ["7", "Gallertartig", "Fell"], ["8", "Leuchtend", "Kiemen"], ["9", "Gehärtet", "Hörner"], ["10", "Kopflos", "Zeichnungen"], ["11", "Gehörnt", "Schuppen"], ["12", "Gebückt", "Schale"], ["13", "Schillernd", "Schnauze"], ["14", "Vieläugig", "Schwanz"], ["15", "Beschuppt", "Krallen"], ["16", "Gegliedert", "Tentakel"], ["17", "Skelettiert", "Rüssel"], ["18", "Schleimig", "Stoßzähne"], ["19", "Durchscheinend", "Stimme"], ["20", "Verdreht", "Flügel"]]}, {"t": "h", "x": "Eigenschaften"}, "Würfle für jede Spalte mit 1W20 und kombiniere die Ergebnisse.", {"t": "tbl", "head": ["W20", "Eigenheit", "Schwäche"], "rows": [["1", "Verändert nach Belieben seine Größe", "Alkohol"], ["2", "Wechselt nach Belieben die Farbe", "Kälte"], ["3", "Sammelt seltene Blumen", "Gespräche"], ["4", "Sammelt Trophäen", "Schmeichelei"], ["5", "Stirbt nicht an Altersschwäche", "Spiele"], ["6", "Zeichnet Symbole", "Geschenke"], ["7", "Von Feuer fasziniert", "Eisen"], ["8", "Hortet Bücher", "Laute Geräusche"], ["9", "Liebt eine bestimmte Farbe", "Spiegel"], ["10", "Wird jeden Tag wiedergeboren", "Grelle Farben"], ["11", "Liebt glänzende Gegenstände", "Mondlicht"], ["12", "Ahmt Stimmen nach", "Musik"], ["13", "Bewegt sich in gerader Linie", "Zubereitete Mahlzeiten"], ["14", "Kommentiert alles, was es tut", "Rätsel"], ["15", "Putzt zwanghaft", "Religiöse Symbole"], ["16", "Pflanzen wachsen in seinem Kielwasser", "Salz"], ["17", "Schläft kopfüber", "Silber"], ["18", "Spricht in Reimen", "Sonnenlicht"], ["19", "Schwitzt seltene Mineralien", "Wahrer Name"], ["20", "Pflanzt sich ungeschlechtlich fort", "Schwachstelle"]]}, {"t": "h", "x": "Angriffe"}, "Würfle für jede Spalte mit 1W20 und kombiniere die Ergebnisse.", {"t": "tbl", "head": ["W20", "Art", "Kritischer Schaden"], "rows": [["1", "Beißt", "Erstickt"], ["2", "Schlägt stumpf", "Blutet"], ["3", "Verbrennt", "Blendet"], ["4", "Friert", "Bricht"], ["5", "Vergast", "Zermalmt"], ["6", "Tritt", "Zersetzt"], ["7", "Boxt", "Löst auf"], ["8", "Schießt", "Verstrickt"], ["9", "Rammt", "Explodiert"], ["10", "Hackt", "Umklammert"], ["11", "Schneidet", "Setzt außer Gefecht"], ["12", "Zerschmettert", "Zerfleischt"], ["13", "Sprüht", "Verflüssigt"], ["14", "Quetscht", "Lähmt"], ["15", "Sticht zu", "Versteinert"], ["16", "Sticht mit dem Stachel", "Vergiftet"], ["17", "Wirft", "Durchbohrt"], ["18", "Berührt", "Trennt ab"], ["19", "Peitscht", "Trampelt nieder"], ["20", "Schockt", "Schwächt"]]}, {"t": "h", "x": "Fähigkeiten"}, "Würfle für jede Spalte mit 1W20 und kombiniere die Ergebnisse.", {"t": "tbl", "head": ["W20", "Fähigkeit", "Ziel"], "rows": [["1", "Absorbiert", "Körper"], ["2", "Verstärkt", "Träume"], ["3", "Zieht an", "Element"], ["4", "Bindet", "Gefühle"], ["5", "Tarnt", "Energie"], ["6", "Beschwört", "Gesundheit"], ["7", "Kontrolliert", "Gehör"], ["8", "Deaktiviert", "Illusionen"], ["9", "Dupliziert", "Licht"], ["10", "Vergrößert", "Erinnerung"], ["11", "Manipuliert", "Metall"], ["12", "Reflektiert", "Pflanzen"], ["13", "Regeneriert", "Geist"], ["14", "Widersteht", "Stein"], ["15", "Kehrt um", "Umgebung"], ["16", "Formt", "Zeit"], ["17", "Verkleinert", "Sicht"], ["18", "Verwandelt", "Wasser"], ["19", "Fängt ein", "Wetter"], ["20", "Schockt", "Schwächung"]]}, {"t": "h", "x": "Monsterbeispiel"}, {"t": "ul", "x": ["**Erscheinung:** Gebückt + Panzer", "**Eigenschaften:** Bewegt sich in gerader Linie + Schwachstelle", "**Angriff:** Zerschmettert + Umklammert", "**Fähigkeiten:** Deaktiviert + Gehör"]}, "Eine schneckenartige Kreatur mit hartem Gehäuse. Sie bewegt sich nur in geraden Linien und hat einen weichen Bauch. Sie rollt auf ihre Gegner zu und zieht sie in ihre wilde Umlaufbahn. Das Dröhnen ihrer Bewegung übertönt jedes andere Geräusch.", "Diese Kreatur ist körperlich zäh, mit überdurchschnittlicher STÄ und starker Rüstung. Sie ist wahrscheinlich schnell, aber nicht wendig und verlässt sich vermutlich nicht auf Geschick oder Gewandtheit, um Gefahren zu entgehen. Sie ist brachial, aber doch ein wildes Tier und nur so willensstark wie jedes Wesen, das bloß nach seiner nächsten Mahlzeit sucht. Sie greift an, indem sie in gerader Linie rollt, und sollte mehrere Ziele treffen.", {"t": "box", "h": "Donnerschnecke", "b": ["TS 6, Rüstung 2, STÄ 14, GES 6, WIL 4, Zerschmettern & Rollen (W10, Streuschaden)", {"t": "ul", "x": ["Dickschalige Bestien, die angreifen, indem sie in gerader Linie über ihre Gegner rollen. Der Lärm ihrer rollenden Schalen ist ohrenbetäubend.", "**Kritischer Schaden:** Das Ziel wird in ihren rollenden Schwung gezogen und verliert jede Runde 1 zusätzliche STÄ, bis es befreit wird (STÄ-Rettungswurf zum Entkommen)."]}]}]});
CN.add("werkzeuge", {"id": "monster-umwandeln", "t": "Monster umwandeln", "p": 110, "buch": "cn_w", "b": ["Es gibt kein perfektes System, um Monster aus anderen Systemen umzuwandeln. Hier sind einige Tipps, die beim Vorgehen helfen können!", {"t": "h", "x": "Werte umrechnen"}, {"t": "dl", "x": [["Trefferschutz", "Als Faustregel gibst du der Kreatur +1 TS pro Trefferwürfel, zusätzlich zu mindestens 3 TS (dem Durchschnittsmenschen). Ich betrachte Trefferwürfel meist als gleichwertig mit einem W6, der im Mittel 3,5 ergibt. Beginne immer mit den TS der Kreatur, danach mit ihrer STÄ."], ["Rüstung", "Suche nach Wendungen wie „wie Leder“ und „wie Plattenpanzer“ in den ursprünglichen Wertekästen. Bei der Umwandlung aus B/X-artigen Spielen wie Old School Essentials ignoriere THAC0 und nutze nach Möglichkeit die absteigende Rüstungsklasse (7 = Leder, 5 = Kettenhemd, 3 = Plattenpanzer). Ist nur die aufsteigende Rüstungsklasse angegeben, kannst du (12 = Leder, 14 = Kettenhemd, 16 = Plattenpanzer) verwenden. Aus welchem System du auch umwandelst: Die Rüstungswerte reichen nur von 1 bis 3."], ["Stärke", "Sieh dir die Trefferwürfel und Trefferpunkte der Kreatur an. Ist eine Kreatur schwer zu töten, aber nicht, weil sie flink oder geschickt ist, gib ihr mehr STÄ (aber nicht mehr TS). Beginne mit 10 STÄ (dem Durchschnitt) und gehe von dort nach oben oder unten."], ["Geschicklichkeit", "Beginne mit 10 als Grundwert und erhöhe die Zahl, wenn die Kreatur besonders schnell (oft als „Geschwindigkeit“ oder SP bezeichnet), gewandt oder fingerfertig ist. Reagiert sie langsam, ist sie sperrig oder tollpatschig, senke die Zahl. Mehr dazu unter Rettungswürfe (S. 112)!"], ["Willenskraft", "Die Moral (ML) kann ein guter Anhaltspunkt sein und liegt meist zwischen 2 und 12. Je größer Persönlichkeit, Geist oder Präsenz der Kreatur, desto höher sollte ihre WIL sein. Die folgende Tabelle bietet eine brauchbare Orientierung für die Umrechnung von ML in WIL."]]}, {"t": "h", "x": "Moral in Willenskraft umrechnen"}, {"t": "tbl", "head": ["ML", "4", "8", "10", "12"], "rows": [["WIL", "6", "12", "15", "18"]]}, {"t": "h", "x": "Rettungswürfe"}, {"t": "ul", "x": ["Du kannst dich auf Rettungswürfe stützen, um mehr über die Fähigkeiten einer Kreatur zu erfahren, insbesondere darüber, wie gut sie tödlichen körperlichen Verletzungen, Magie oder Gift entgehen kann.", "Wertekästen verwenden eine Kurzschreibweise wie (E1) oder (F1) (Elf bzw. Kämpfer der Stufe 1). Sie helfen, die Fähigkeiten der Kreatur schnell zu erfassen.", "Erwäge, beschreibende Merkmale wie „immun gegen Giftgas“ oder „gut im Ausweichen“ anhand der Rettungswürfe hinzuzufügen. Die folgende Tabelle hilft dir zu bestimmen, welche Rettungswürfe zur Erhöhung eines der betreffenden Attributswerte führen sollten."]}, {"t": "h4", "x": "Rettungswürfe umrechnen"}, {"t": "tbl", "head": ["Rettungswurf", "Attribut"], "rows": [["Tod oder Gift", "STÄ"], ["Zauberstäbe", "GES"], ["Lähmung oder Versteinerung", "WIL oder STÄ"], ["Odemangriffe", "GES oder STÄ"], ["Zauber, Zepter oder Stäbe", "WIL"]]}, {"t": "h", "x": "Kampf"}, {"t": "ul", "x": ["**Schadenswürfel:** Lässt sich bei den meisten OSR-Systemen in der Regel unverändert übernehmen, aber vergleiche zuerst mit den im Marktplatz aufgeführten Waffen (siehe Spielerhandbuch).", "**Mehrfachangriffe:** In Streuschaden oder in mehrere Würfel umwandeln (z. B. W6+W6).", "**Verheerende Angriffe:** Erwäge, den Schaden zu verstärken, die Eigenschaft Streuschaden zu vergeben oder dem Angriff mehrere Würfel zu geben."]}, {"t": "h", "x": "Fähigkeiten"}, {"t": "ul", "x": ["Manchmal lassen sich die Mechaniken des ursprünglichen Systems einfach nicht übertragen. Das ist in Ordnung! Konzentriere dich darauf, was an der Kreatur am interessantesten ist, und schreibe eine „Version“ ihrer Fähigkeit, die besser zu Cairn passt.", "Fähigkeiten lassen sich manchmal in Angriffe (mit Schadenswürfel) umwandeln, sodass der kritische Schaden die wahre Wirkung zeigt.", "Hat das Monster einen Angriff, bei dem die SC ausweichen oder einen Rettungswurf gegen eine Fähigkeit ablegen sollen, erwäge, die Fähigkeit zu einer „Falle“ außerhalb des Kampfes zu machen, die die SC auslösen können. Andernfalls lass sie automatisch gelingen. Kämpfe sind gefährlich, und es liegt an der Spielleitung, Gefahren vor Kampfbeginn angemessen anzukündigen."]}, {"t": "h", "x": "Magie"}, {"t": "ul", "x": ["Magische Kreaturen können eine Menge Zauber „kennen“, ohne Zauberbücher mit sich zu führen. Mach in diesem Fall ihre Leichen magisch (und gefährlich)!", "Zauber sind heikel; du kannst Magiewirkenden Zauberbücher geben, aber denke daran, dass sie diese beim Besiegtwerden fallen lassen könnten.", "Erwäge, einige der fallen gelassenen Zauberbücher implodieren zu lassen (nutze den Schicksalswürfel, um zu bestimmen, welche)."]}, {"t": "h", "x": "Die Fiktion nutzen"}, "Der einfachste Weg, ein Monster aus einem anderen System umzuwandeln, ist, den ursprünglichen Wertekasten und den zugehörigen Text zu lesen, ein paar Sätze über die Kreatur in einfachen Worten zu schreiben und das Geschriebene schließlich in den Cairn-Wertekasten zu übertragen.", "Nimm zum Beispiel diese Kreatur:", {"t": "box", "h": "Fuchsfrau (Original)", "b": ["Kann die Gestalt eines Fuchses oder einer 2 m großen Frau mit Fuchskopf annehmen.", "TW 5, Bewegung 36 m, Rüstungsklasse 14, Moral 11, Angriff: +4 W8 TP (Klaue, Biss oder Würgen)", {"t": "ul", "x": ["Verteidigung: Kann durch Metall nicht verletzt werden.", "Besonderes: Kann sich nach Belieben in einen Fuchs oder eine Maid mit einem versteckten Fuchsbein verwandeln (gleiche Werte)."]}]}, "Anhand des obigen Beispiels erkenne ich, dass sie:", {"t": "ul", "x": ["als 2 m große menschliche Frau mit dem Kopf eines Fuchses erscheint.", "keine übermäßig hohen TP hat und ziemlich schnell ist.", "eine ziemlich hohe ML hat und offensichtlich recht willensstark ist.", "gewandt und geschmeidig ist.", "mit Zähnen und Klauen angreift (und ihre Beute würgt, wenn möglich).", "sich nach Belieben in einen Fuchs verwandeln kann.", "immun gegen Metallwaffen ist."]}, "Was können wir daraus lernen?", {"t": "ul", "x": ["Sie ist schnell und im Kampf wahrscheinlich gerissen. Wenn wir bei 3 TS beginnen und 1 TS pro Trefferwürfel hinzufügen, hat sie 8 TS.", "Ich glaube nicht, dass Füchse schützende Häute haben, und abgesehen vom Kopf ist sie ein Mensch. Keine Rüstung.", "Sie ist ziemlich kräftig. Ein normaler Mensch hat 10 STÄ, und sie ist etwas größer. 12 STÄ.", "Ich kann mir vorstellen, wie sie ihrer Beute über die verschneite Tundra nachjagt. Sie ist schnell. 14 GES.", "Ihre ML ist hoch, und Füchse sind für ihre Gerissenheit bekannt. 15 WIL.", "Für ihre Angriffe würde ich Klauen (W6+W6) und Biss (W8) wählen."]}, "Diese Informationen führen uns zu Folgendem:", "8 TS, 12 STÄ, 14 GES, 15 WIL, Klauen (W6+W6), Biss (W8)", "Nun zu ihren Fähigkeiten. Das ist recht einfach: Wir lesen einfach den fiktiven Wertekasten, den wir zuvor geschrieben haben!", {"t": "ul", "x": ["Sie erscheint als 2 m große menschliche Frau mit dem Bein eines Fuchses.", "Sie kann sich nach Belieben in einen Fuchs verwandeln.", "Sie ist immun gegen Angriffe mit Metallwaffen.", "Sie würgt ihre Opfer bis zur Bewusstlosigkeit."]}, "Das Endergebnis:", {"t": "box", "h": "Fuchsfrau", "b": ["TS 8, STÄ 12, GES 14, WIL 15, Klauen (W6+W6), Biss (W8)", {"t": "ul", "x": ["Kann die Gestalt eines Fuchses oder einer Frau mit verstecktem Fuchsbein annehmen.", "Immun gegen Angriffe mit Metallwaffen.", "**Kritischer Schaden:** Das Opfer wird bis zur Bewusstlosigkeit gewürgt."]}]}]});
CN.add("werkzeuge", {"id": "monster-kategorien", "t": "Monsterkategorien", "p": 114, "buch": "cn_w", "b": [{"t": "tbl", "head": ["W20", "Gruppentyp", "Monster"], "rows": [["1", "Vogelartig", "Phönix, Rok, Wyvern"], ["2", "Bestie", "Blutelch, Grizzlybär, Killerbienen, Nachtkatze, Viper, Wolf"], ["3", "Gigant", "Grüner Drache, Purpurwurm"], ["4", "Konstrukt", "Knochenkonstrukt, Kopfsteinhunde, Gargyl"], ["5", "Dämon", "Höllenhund, Nachtmahr"], ["6", "Außerweltlich", "Auge des Schreckens, Geistgeißler"], ["7", "Feenwesen", "Boggart, Dryade, Frostelf, Pixie, Rotkappe, Nachthexe, Seehexe, Irrlicht"], ["8", "Riese", "Ettin, Himmelsriese, Sturmriese, Titan"], ["9", "Goblinartig", "Bugbear, Goblin, Hobgoblin, Oger, Wurzelgoblin, Troll, Waldtroll"], ["10", "Humanoid", "Akolyth, Bandit, Frostelf, Gnoll, Kapuzenmänner, Triton"], ["11", "Mischwesen", "Zentaur, Mantikor, Minotaurus, Eulenbär"], ["12", "Körperlos", "Unsichtbarer Häscher, Schatten"], ["13", "Insektenartig", "Aranea, Grabschrecken, Höhlenheuschrecke, Riesenskorpion"], ["14", "Echse", "Basilisk, Hydra, Kobold, Naga, Reptilienwesen"], ["15", "Magisch", "Blinzelhund, Verzerrungspanther, Wasserelementar"], ["16", "Mythisch", "Banshee, Greif, Harpyie, Hydra, Lamia, Einhorn"], ["17", "Pflanze", "Kriechranken, Wurzelhexe, Schlurfhügel, Baumhirte"], ["18", "Gestaltwandler", "Schweinewesen, Werwolf"], ["19", "Untot", "Kryptenwächter, Geist, Ghul, Lich, Mumie, Skelett, Vampir, Grabunhold, Zombie"], ["20", "Ungewöhnlich", "Gallertschleim, Mimik, Rostmonster, Kampfschnecke"]]}]});
CN.add("werkzeuge", {"id": "namen-verfahren", "t": "Namensverfahren", "p": 116, "buch": "cn_w", "b": [{"t": "h", "x": "Grundsätze"}, {"t": "ul", "x": ["Siedlungen werden oft nach ihren besonderen Merkmalen benannt: der Form des nahen Flusses oder der großen Windmühle in der Ortsmitte. Die Bewohner fügen dann ein Nomen oder Adjektiv hinzu: Windige Schlucht, Schwarzbaumfeste usw.", "Wichtige Orte sollten wichtige Namen tragen, etwa die von Helden, religiösen oder politischen Persönlichkeiten und anderen Ereignissen. Das Chalet der Heiligen Ibiz, Königinnenernte, Licht der Neun usw.", "Eigennamen können Teile eines Namens ergänzen oder sogar ersetzen, z. B. Brunas hässliche Schlucht.", "Wilde und gefährliche Orte werden nach offensichtlichen Gefahren benannt: Giftsee, Nebelklippen usw.", "Manche Namen erzählen eine Geschichte: Lukas Torheit, Pfad des Toten usw.", "Nutze das örtliche Gelände der Region und die Besonderheiten des Ortes, wo es passt."]}, {"t": "h", "x": "Namen erzeugen"}, {"t": "ul", "x": ["Würfle für jeden Ort von Interesse auf der Tabelle Namensformel.", "Würfle bei Bedarf auf den Tabellen Adjektive und Nomen.", "Um 1W100 zu würfeln, wirf 2W10: einen Würfel für die Zehnerstelle und einen für die Einerstelle.", "Um Regionen nach ihrem Gelände zu benennen, ersetze „Ort“ durch die Geländeart und sieh dir die Tabelle Geländesynonyme zur Inspiration an."]}, {"t": "d", "h": "Namensformel", "die": "W6", "rows": ["(Das) [Nomen] [Ort]", "(Das) [Adjektiv] [Ort]", "[Ort] von (dem) [Nomen]", "[Adjektiv] [Ort] von (dem) [Nomen]", "(Das) [Nomen] [Adjektiv] [Ort]", "[Ort] von (dem) [Adjektiv] [Nomen]"]}, {"t": "h", "x": "Geländesynonyme"}, {"t": "tbl", "head": ["Gelände", "Synonym"], "rows": [["Strände", "Küste, Ufer, Gestade, Seeküste, Vorstrand, Hafenbucht"], ["Moore", "Sumpf, Morast, Schlick, Niederung, Fenn"], ["Schluchten", "Klamm, Rinne, Spalt, Abgrund, Kluft, Tobel"], ["Höhlen", "Grotte, Hohlraum, Stollen, Erdhöhle, Kaverne"], ["Klippen", "Steilwand, Felswand, Fels, Steilufer, Grat, Böschung, Steilhang"], ["Wüste", "Dünen, Sande, Weiten, Ödland, Brache, Sandmeer"], ["Ackerland", "Feldflur, Gehöft, Flur, Gut, Meierei, Plantage"], ["Wald", "Busch, Gehölz, Waldland, Weald, Hain, Wäldchen"], ["Grasland", "Weide, Steppe, Savanne, Felder, Grünland"], ["Hügel", "Hügelchen, Anhöhe, Berg, Kuppe, Buckel, Hang"], ["Mulden", "Senke, Loch, Grube, Höhlung, Krater, Trog, Löcher"], ["Dschungel", "Siehe Wald"], ["Seen", "Teich, Tümpel, Bergsee, Lagune, Loch, Bayou"], ["Berge", "Gipfel, Grat, Gebirge, Spitze, Zinne, Zeugenberg"], ["Oase", "Quelle, Brunnen, Born, Zuflucht, Tränke, Rastplatz"], ["Ebenen", "Heide, Wiese, Veld, Flachland, Tiefland, Grasnarbe"], ["Plateau", "Hochland, Mesa, Hochebene, Höhen, Weite"], ["Fluss", "Wasserlauf, Strom, Bach, Rinnsal, Creek, Kanal"], ["Meer", "Siehe Strände"], ["Sumpf", "Moor, Morast, Bruch, Heidemoor, Senke, Feuchtgebiet"], ["Dickichte", "Macchia, Gestrüpp, Dickung, Niederwald, Felsheide"], ["Tundra", "Weite, Prärie, Taiga, Brache"], ["Tal", "Aue, Tal, Becken, Schlucht, Pass, Talmulde"], ["Ödland", "Siehe Wüste"]]}]});
